  LocalizedMessage get privacyCaptureUnreadable => LocalizedMessage(
    key: 'privacyCaptureUnreadable',
    fallback: Copy.privacyCaptureUnreadable,
  );

  /// Recover the capture and try again.
  LocalizedMessage get privacyCaptureRecover => LocalizedMessage(
