    fallback: Copy.privacyCaptureRecover,
  );

  /// Open a project before removing its location data.
  LocalizedMessage get privacyProjectRequired => LocalizedMessage(
    key: 'privacyProjectRequired',
    fallback: Copy.privacyProjectRequired,
  );

  /// Choose a project, then try again.
  LocalizedMessage get privacyProjectRequiredRecovery => LocalizedMessage(
    key: 'privacyProjectRequiredRecovery',
    fallback: Copy.privacyProjectRequiredRecovery,
  );

  /// This destination sign-in changed.
  LocalizedMessage get cloudSignInChanged => LocalizedMessage(
    key: 'cloudSignInChanged',
    fallback: Copy.cloudSignInChanged,
  );

  /// This Google Drive sign-in needs renewal.
  LocalizedMessage get cloudGoogleSignInRenewal => LocalizedMessage(
